            connectToSageIntacct(policyID, values);
            Navigation.dismissModal();
        },
        [policyID],
    );

    const formItems = Object.values(INPUT_IDS);
    const validate = useCallback(
        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.SAGE_INTACCT_CREDENTIALS_FORM>) => {
